// JetBrains Mono Bold (SIL Open Font License 1.1), embedded for the typewriter / VHS text.
const MONO_FONT = 'ZMono';
const MONO_READY = (() => { try { const f = new FontFace(MONO_FONT, 'url(data:font/ttf;base64,)'); document.fonts.add(f); return f.load(); } catch (e) { return Promise.resolve(); } })();
